// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	if loadBalancerName == "" || outputFile == "" {
		return "", fmt.Errorf("loadBalancerName and outputFile cannot be empty")
	}

	// Command 1: aliyun CLI
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Command 2: jq filter
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe to connect aliyun's stdout to jq's stdin
	aliyunStdout, err := cmdAliyun.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe for aliyun: %w", err)
	}
	cmdJq.Stdin = aliyunStdout

	// Buffer to capture the final output from jq
	var outBuf bytes.Buffer
	cmdJq.Stdout = &outBuf

	// Capture stderr for both commands to aid debugging
	var errBuf bytes.Buffer
	cmdAliyun.Stderr = &errBuf
	cmdJq.Stderr = &errBuf

	// Start the first command
	if err := cmdAliyun.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start the second command
	if err := cmdJq.Start(); err != nil {
		cmdAliyun.Process.Kill()
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to finish
	errAliyun := cmdAliyun.Wait()
	errJq := cmdJq.Wait()

	outputStr := outBuf.String()

	// Check for execution errors
	if errAliyun != nil {
		return outputStr, fmt.Errorf("aliyun command failed: %w, stderr: %s", errAliyun, errBuf.String())
	}
	if errJq != nil {
		return outputStr, fmt.Errorf("jq command failed: %w, stderr: %s", errJq, errBuf.String())
	}

	// Write the captured output to the specified file
	if err := os.WriteFile(outputFile, []byte(outputStr), 0644); err != nil {
		return outputStr, fmt.Errorf("failed to write output to file: %w", err)
	}

	return outputStr, nil
}

