package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// SECURITY FIX: Prevent directory traversal for user-controlled file paths
	cleanPath := filepath.Clean(outputFile)
	if strings.Contains(cleanPath, "..") {
		return "", fmt.Errorf("invalid output file path: path traversal detected")
	}

	// SECURITY FIX: Avoid using "sh -c" with string formatting.
	// Directly pass arguments to exec.Command to completely eliminate shell injection risks.
	// User-controlled inputs are passed as literal arguments and never interpreted by a shell.
	cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Programmatically create the pipeline: cmd1 | cmd2
	stdoutPipe, err := cmd1.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	cmd2.Stdin = stdoutPipe

	// Buffers to capture stdout and stderr separately (bytes.Buffer is not concurrency-safe)
	var stdoutBuf, stderrBuf1, stderrBuf2 bytes.Buffer
	cmd2.Stdout = &stdoutBuf
	cmd1.Stderr = &stderrBuf1
	cmd2.Stderr = &stderrBuf2

	// Start the first command
	if err := cmd1.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start the second command
	if err := cmd2.Start(); err != nil {
		cmd1.Process.Kill() // Clean up cmd1 if cmd2 fails to start
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to finish
	err1 := cmd1.Wait()
	err2 := cmd2.Wait()

	// Handle execution errors with detailed stderr output
	if err1 != nil {
		return stdoutBuf.String(), fmt.Errorf("aliyun command failed: %w, stderr: %s", err1, stderrBuf1.String())
	}
	if err2 != nil {
		return stdoutBuf.String(), fmt.Errorf("jq command failed: %w, stderr: %s", err2, stderrBuf2.String())
	}

	outputStr := stdoutBuf.String()

	// Securely write the captured output to the file (replaces shell redirection '>')
	if err := os.WriteFile(cleanPath, []byte(outputStr), 0644); err != nil {
		return outputStr, fmt.Errorf("failed to write output file: %w", err)
	}

	return outputStr, nil
}

