package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI to describe SLB instances,
// pipes the output to jq for formatting, writes the result to a file,
// and returns the formatted output string.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Command 1: aliyun slb DescribeLoadBalancers
	cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Command 2: jq filter
	cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Pipe stdout of cmd1 to stdin of cmd2
	stdoutPipe, err := cmd1.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	cmd2.Stdin = stdoutPipe

	// Prepare output file and in-memory buffer to capture the result
	file, err := os.Create(outputFile)
	if err != nil {
		return "", fmt.Errorf("failed to create output file %s: %w", outputFile, err)
	}
	defer file.Close()

	var outBuf bytes.Buffer
	// Write jq output to both the file and the buffer simultaneously
	cmd2.Stdout = io.MultiWriter(file, &outBuf)

	// Capture stderr from both commands for detailed error reporting
	var errBuf bytes.Buffer
	cmd1.Stderr = &errBuf
	cmd2.Stderr = &errBuf

	// Start the consumer (jq) first
	if err := cmd2.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Run the producer (aliyun) and wait for it to finish.
	// This automatically closes the stdout pipe, signaling EOF to jq.
	if err := cmd1.Run(); err != nil {
		return "", fmt.Errorf("aliyun command failed: %w | stderr: %s", err, errBuf.String())
	}

	// Wait for jq to finish processing the piped input
	if err := cmd2.Wait(); err != nil {
		return "", fmt.Errorf("jq command failed: %w | stderr: %s", err, errBuf.String())
	}

	return outBuf.String(), nil
}

func main() {
	if len(os.Args) < 3 {
		fmt.Println("Usage: go run main.go <LoadBalancerName> <OutputFile>")
		os.Exit(1)
	}

	result, err := QuerySLBAndExport(os.Args[1], os.Args[2])
	if err != nil {
		fmt.Fprintf(os.Stderr, "Execution failed: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("Successfully exported SLB information to %s\n", os.Args[2])
	fmt.Println("Command output:")
	fmt.Println(result)
}

