package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Use exec.Command directly with argument slices to completely eliminate
	// shell injection risks. This avoids the unsafe `sh -c` string concatenation.
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Pipe aliyun's stdout to jq's stdin (equivalent to shell `|`)
	aliyunStdout, err := cmdAliyun.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe for aliyun: %w", err)
	}
	cmdJq.Stdin = aliyunStdout

	// Open output file for writing (equivalent to shell `>`)
	outFile, err := os.Create(outputFile)
	if err != nil {
		return "", fmt.Errorf("failed to create output file '%s': %w", outputFile, err)
	}
	defer outFile.Close()

	// Capture jq's stdout to both the file and a buffer for returning
	var outBuf bytes.Buffer
	cmdJq.Stdout = io.MultiWriter(outFile, &outBuf)

	// Capture stderr from both commands for detailed error reporting
	var errBuf bytes.Buffer
	cmdAliyun.Stderr = &errBuf
	cmdJq.Stderr = &errBuf

	// Start the aliyun command
	if err := cmdAliyun.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start the jq command
	if err := cmdJq.Start(); err != nil {
		cmdAliyun.Process.Kill() // Clean up aliyun process if jq fails to start
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to complete
	errAliyun := cmdAliyun.Wait()
	errJq := cmdJq.Wait()

	// Check for execution errors
	if errAliyun != nil {
		return outBuf.String(), fmt.Errorf("aliyun command failed: %w, stderr: %s", errAliyun, errBuf.String())
	}
	if errJq != nil {
		return outBuf.String(), fmt.Errorf("jq command failed: %w, stderr: %s", errJq, errBuf.String())
	}

	return outBuf.String(), nil
}

