package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Use native Go piping instead of `sh -c` to completely eliminate shell injection risks,
	// avoid fragile input validation, and correctly capture stdout while writing to a file.

	// Command 1: aliyun slb DescribeLoadBalancers
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Command 2: jq filter
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Pipe aliyun's stdout to jq's stdin
	aliyunStdout, err := cmdAliyun.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe for aliyun: %w", err)
	}
	cmdJq.Stdin = aliyunStdout

	// Create the output file
	outF, err := os.Create(outputFile)
	if err != nil {
		return "", fmt.Errorf("failed to create output file: %w", err)
	}
	defer outF.Close()

	// Buffer to capture output for the return value
	var outBuf bytes.Buffer

	// Write jq's stdout to both the file and the buffer simultaneously
	cmdJq.Stdout = io.MultiWriter(outF, &outBuf)

	// Capture stderr from both commands for better error reporting
	var stderrBuf bytes.Buffer
	cmdAliyun.Stderr = &stderrBuf
	cmdJq.Stderr = &stderrBuf

	// Start jq first, then aliyun
	if err := cmdJq.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq: %w", err)
	}
	if err := cmdAliyun.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun: %w", err)
	}

	// Wait for aliyun to finish. Its stdout pipe will automatically close, sending EOF to jq.
	if err := cmdAliyun.Wait(); err != nil {
		return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", err, stderrBuf.String())
	}

	// Wait for jq to finish processing
	if err := cmdJq.Wait(); err != nil {
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", err, stderrBuf.String())
	}

	return outBuf.String(), nil
}

