package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// 1. Input Validation
	if strings.TrimSpace(loadBalancerName) == "" || strings.TrimSpace(outputFile) == "" {
		return "", fmt.Errorf("parameters cannot be empty")
	}

	// Sanitize output file path to prevent directory traversal attacks
	outputFile = filepath.Clean(outputFile)

	// 2. Secure Command Execution (No Shell Invocation)
	// Instead of using `sh -c` with string concatenation (which is vulnerable to command injection),
	// we pass arguments directly to exec.Command. This completely neutralizes injection risks.

	// Step A: Run aliyun CLI
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	var aliyunOut, aliyunErr bytes.Buffer
	cmdAliyun.Stdout = &aliyunOut
	cmdAliyun.Stderr = &aliyunErr

	if err := cmdAliyun.Run(); err != nil {
		return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", err, aliyunErr.String())
	}

	// Step B: Run jq, piping the output from aliyun programmatically
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
	cmdJq.Stdin = &aliyunOut
	var jqOut, jqErr bytes.Buffer
	cmdJq.Stdout = &jqOut
	cmdJq.Stderr = &jqErr

	if err := cmdJq.Run(); err != nil {
		// Return whatever jq managed to output before failing
		return jqOut.String(), fmt.Errorf("jq command failed: %w, stderr: %s", err, jqErr.String())
	}

	// 3. Capture Result & Export to File
	result := jqOut.String()

	// Handle file redirection securely in Go instead of using shell `>`
	if err := os.WriteFile(outputFile, []byte(result), 0644); err != nil {
		return result, fmt.Errorf("failed to write output to file: %w", err)
	}

	return result, nil
}

