package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
// Security Fix: Replaced vulnerable `sh -c` string interpolation with direct
// exec.Command calls and programmatic piping to prevent OS Command Injection (CWE-78).
// Arguments are passed as literal strings, neutralizing all shell metacharacters.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	if loadBalancerName == "" || outputFile == "" {
		return "", fmt.Errorf("parameters cannot be empty")
	}

	// Clean the output file path to mitigate basic path traversal issues
	cleanOutputFile := filepath.Clean(outputFile)

	// Construct commands directly without invoking a shell.
	// This treats all arguments as literal strings, completely preventing command injection.
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe to connect aliyun's stdout to jq's stdin
	aliyunStdout, err := cmdAliyun.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	cmdJq.Stdin = aliyunStdout

	// Buffers to capture output and errors separately to avoid concurrent write races
	var stdoutBuf, aliyunErrBuf, jqErrBuf bytes.Buffer
	cmdJq.Stdout = &stdoutBuf
	cmdJq.Stderr = &jqErrBuf
	cmdAliyun.Stderr = &aliyunErrBuf

	// Start the first command
	if err := cmdAliyun.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start the second command
	if err := cmdJq.Start(); err != nil {
		cmdAliyun.Process.Kill() // Clean up if jq fails to start
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to complete
	errAliyun := cmdAliyun.Wait()
	errJq := cmdJq.Wait()

	outputStr := stdoutBuf.String()

	// Write the processed output to the target file (equivalent to shell '>')
	if err := os.WriteFile(cleanOutputFile, []byte(outputStr), 0644); err != nil {
		return outputStr, fmt.Errorf("failed to write output file: %w", err)
	}

	// Return captured output and handle potential execution errors
	if errAliyun != nil {
		return outputStr, fmt.Errorf("aliyun command failed: %w, stderr: %s", errAliyun, aliyunErrBuf.String())
	}
	if errJq != nil {
		return outputStr, fmt.Errorf("jq command failed: %w, stderr: %s", errJq, jqErrBuf.String())
	}

	return outputStr, nil
}

