package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI to describe SLB instances,
// pipes the output to jq for formatting, and writes the result to a file.
// It returns the formatted output string and any execution error.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Command 1: aliyun slb DescribeLoadBalancers
	cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Command 2: jq filter
	cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe: stdout of cmd1 -> stdin of cmd2
	stdout1, err := cmd1.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe for aliyun command: %w", err)
	}
	cmd2.Stdin = stdout1

	// Capture stderr from both commands for debugging/error reporting
	var stderrBuf bytes.Buffer
	cmd1.Stderr = &stderrBuf
	cmd2.Stderr = &stderrBuf

	// Open/Create the output file
	outF, err := os.Create(outputFile)
	if err != nil {
		return "", fmt.Errorf("failed to create output file: %w", err)
	}
	defer outF.Close()

	// Buffer to capture the final result (stdout of jq)
	var resultBuf bytes.Buffer
	// Tee the output: write to both the file and the in-memory buffer
	cmd2.Stdout = io.MultiWriter(outF, &resultBuf)

	// Start both commands
	if err := cmd1.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}
	if err := cmd2.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to complete
	err1 := cmd1.Wait()
	err2 := cmd2.Wait()

	// Handle errors, prioritizing the upstream command failure
	if err1 != nil {
		return stderrBuf.String(), fmt.Errorf("aliyun command failed: %w", err1)
	}
	if err2 != nil {
		return stderrBuf.String(), fmt.Errorf("jq command failed: %w", err2)
	}

	return resultBuf.String(), nil
}

func main() {
	// Example usage
	lbName := "my-production-slb"
	outFile := "output.json"

	result, err := QuerySLBAndExport(lbName, outFile)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Execution failed: %v\n", err)
		if result != "" {
			fmt.Fprintf(os.Stderr, "Command stderr/output:\n%s\n", result)
		}
		os.Exit(1)
	}

	fmt.Printf("Successfully exported SLB information to %s\n", outFile)
	if result != "" {
		fmt.Printf("Captured output:\n%s\n", result)
	}
}

