// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	if loadBalancerName == "" || outputFile == "" {
		return "", fmt.Errorf("loadBalancerName and outputFile cannot be empty")
	}

	// Use native exec.Command to construct the pipeline safely.
	// This completely avoids shell injection vulnerabilities associated with sh -c
	// and removes the need for manual character escaping/validation.
	cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Pipe stdout of cmd1 to stdin of cmd2
	stdout1, err := cmd1.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	cmd2.Stdin = stdout1

	// Capture final stdout and stderr separately to avoid concurrent write races
	var outBuf bytes.Buffer
	cmd2.Stdout = &outBuf

	var errBuf1, errBuf2 bytes.Buffer
	cmd1.Stderr = &errBuf1
	cmd2.Stderr = &errBuf2

	// Start both commands
	if err := cmd1.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}
	if err := cmd2.Start(); err != nil {
		cmd1.Wait() // Ensure cmd1 is cleaned up if cmd2 fails to start
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to complete
	err1 := cmd1.Wait()
	err2 := cmd2.Wait()

	if err1 != nil {
		return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", err1, errBuf1.String())
	}
	if err2 != nil {
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", err2, errBuf2.String())
	}

	outputBytes := outBuf.Bytes()

	// Write the captured output to the specified file programmatically.
	// This replaces the shell '>' redirection, allowing us to both export the file
	// and return the stdout content as required.
	if err := os.WriteFile(outputFile, outputBytes, 0644); err != nil {
		return "", fmt.Errorf("failed to write output to file: %w", err)
	}

	return string(outputBytes), nil
}

