import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	if loadBalancerName == "" || outputFile == "" {
		return "", fmt.Errorf("parameters cannot be empty")
	}

	// Security Fix: Avoid using `sh -c` with string interpolation to prevent command injection.
	// Instead, pass arguments directly to exec.Command, which bypasses shell parsing entirely.
	// Shell redirection (`>`) is replaced with Go's native file I/O for safety.

	// Step 1: Execute aliyun command securely
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	aliyunOut, err := cmdAliyun.CombinedOutput()
	if err != nil {
		return string(aliyunOut), fmt.Errorf("aliyun command failed: %w, output: %s", err, string(aliyunOut))
	}

	// Step 2: Execute jq command securely, piping aliyun output via stdin
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
	cmdJq.Stdin = bytes.NewReader(aliyunOut)
	jqOut, err := cmdJq.CombinedOutput()
	if err != nil {
		return string(jqOut), fmt.Errorf("jq command failed: %w, output: %s", err, string(jqOut))
	}

	// Step 3: Write output to file securely using Go's os package instead of shell redirection
	cleanPath := filepath.Clean(outputFile)
	err = os.WriteFile(cleanPath, jqOut, 0644)
	if err != nil {
		return string(jqOut), fmt.Errorf("failed to write output file: %w", err)
	}

	return string(jqOut), nil
}

