		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to complete
	errAliyun := cmdAliyun.Wait()
	errJq := cmdJq.Wait()

	if errAliyun != nil {
		return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", errAliyun, aliyunStderr.String())
	}
	if errJq != nil {
