// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// 1. Strict input validation (Defense in Depth)
	// Allow only safe characters for SLB names. Since we bypass the shell,
	// this is primarily for business logic safety and defense-in-depth.
	validName := regexp.MustCompile(`^[a-zA-Z0-9._-]+$`)
	if !validName.MatchString(loadBalancerName) {
		return "", fmt.Errorf("invalid loadBalancerName: only alphanumeric characters, dots, hyphens, and underscores are allowed")
	}

	// Clean and validate output file path to prevent path traversal attacks
	cleanPath := filepath.Clean(outputFile)
	if strings.Contains(cleanPath, "..") {
		return "", fmt.Errorf("invalid outputFile: path traversal is not allowed")
	}

	// 2. Execute 'aliyun' command directly without invoking a shell.
	// Passing arguments as a slice completely eliminates shell injection vulnerabilities.
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	aliyunOut, err := cmdAliyun.Output()
	if err != nil {
		return "", fmt.Errorf("aliyun command failed: %w", err)
	}

	// 3. Execute 'jq' command directly, piping the output programmatically.
	// This safely replaces the shell '|' operator.
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")
	cmdJq.Stdin = bytes.NewReader(aliyunOut)
	jqOut, err := cmdJq.Output()
	if err != nil {
		return "", fmt.Errorf("jq command failed: %w", err)
	}

	// 4. Write output to file programmatically.
	// This safely replaces the shell '>' redirection and avoids filename injection.
	if err := os.WriteFile(cleanPath, jqOut, 0644); err != nil {
		return "", fmt.Errorf("failed to write output file: %w", err)
	}

	return string(jqOut), nil
}

