package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	if loadBalancerName == "" || outputFile == "" {
		return "", fmt.Errorf("parameters cannot be empty")
	}

	// Use native os/exec piping instead of "sh -c" to completely eliminate
	// shell injection risks and handle streams more robustly.
	cmdAliyun := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Pipe aliyun stdout to jq stdin
	aliyunStdout, err := cmdAliyun.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	cmdJq.Stdin = aliyunStdout

	// Capture outputs
	var stdoutBuf, stderrBuf bytes.Buffer
	cmdAliyun.Stderr = &stderrBuf
	cmdJq.Stdout = &stdoutBuf
	cmdJq.Stderr = &stderrBuf

	// Start the pipeline
	if err := cmdAliyun.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}
	if err := cmdJq.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for completion
	errAliyun := cmdAliyun.Wait()
	errJq := cmdJq.Wait()

	outputStr := stdoutBuf.String()
	stderrStr := stderrBuf.String()

	if errAliyun != nil {
		return outputStr, fmt.Errorf("aliyun command failed: %w, stderr: %s", errAliyun, stderrStr)
	}
	if errJq != nil {
		return outputStr, fmt.Errorf("jq command failed: %w, stderr: %s", errJq, stderrStr)
	}

	// Export to file
	if err := os.WriteFile(outputFile, []byte(outputStr), 0644); err != nil {
		return outputStr, fmt.Errorf("failed to write output file: %w", err)
	}

	return outputStr, nil
}

