// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Validate inputs to prevent empty values
	if strings.TrimSpace(loadBalancerName) == "" || strings.TrimSpace(outputFile) == "" {
		return "", fmt.Errorf("parameters cannot be empty")
	}

	// Clean the output file path to prevent directory traversal attacks
	safeOutputPath := filepath.Clean(outputFile)
	if strings.HasPrefix(safeOutputPath, "..") {
		return "", fmt.Errorf("invalid output file path: directory traversal not allowed")
	}

	// SECURITY FIX: Avoid shell execution (sh -c) to completely eliminate command injection risks.
	// Pass arguments directly to exec.Command so the OS handles them safely without shell parsing.
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe to connect aliyun's stdout to jq's stdin (replaces shell '|')
	aliyunStdout, err := aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	jqCmd.Stdin = aliyunStdout

	// Capture jq's stdout
	var outputBuf bytes.Buffer
	jqCmd.Stdout = &outputBuf

	// Capture stderr separately for each command to avoid concurrent write race conditions
	var aliyunErrBuf, jqErrBuf bytes.Buffer
	aliyunCmd.Stderr = &aliyunErrBuf
	jqCmd.Stderr = &jqErrBuf

	// Start the aliyun command
	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start the jq command
	if err := jqCmd.Start(); err != nil {
		aliyunCmd.Process.Kill() // Clean up aliyun process if jq fails to start
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to complete.
	// aliyunCmd.Wait() closes the pipe write-end, signaling EOF to jq.
	if err := aliyunCmd.Wait(); err != nil {
		return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", err, aliyunErrBuf.String())
	}
	if err := jqCmd.Wait(); err != nil {
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", err, jqErrBuf.String())
	}

	// Retrieve pipeline output
	outputBytes := outputBuf.Bytes()
	outputStr := string(outputBytes)

	// Securely write output to file (replaces shell '>')
	if err := os.WriteFile(safeOutputPath, outputBytes, 0644); err != nil {
		return outputStr, fmt.Errorf("failed to write output file: %w", err)
	}

	return outputStr, nil
}

