// QuerySLBAndExport executes the aliyun CLI to describe SLBs, pipes the output to jq,
// and writes the filtered result to the specified output file.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Command 1: aliyun slb DescribeLoadBalancers
	cmd1 := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)

	// Command 2: jq filter
	cmd2 := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe to connect cmd1's stdout to cmd2's stdin
	stdoutPipe, err := cmd1.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	cmd2.Stdin = stdoutPipe

	// Open the output file for writing (equivalent to shell redirection >)
	outF, err := os.Create(outputFile)
	if err != nil {
		return "", fmt.Errorf("failed to create output file: %w", err)
	}
	defer outF.Close()
	cmd2.Stdout = outF

	// Capture stderr from both commands for debugging/error reporting
	var stderrBuf bytes.Buffer
	cmd1.Stderr = &stderrBuf
	cmd2.Stderr = &stderrBuf

	// Start the first command
	if err := cmd1.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start the second command
	if err := cmd2.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to complete
	err1 := cmd1.Wait()
	err2 := cmd2.Wait()

	result := stderrBuf.String()
	if err1 != nil {
		return result, fmt.Errorf("aliyun command failed: %w", err1)
	}
	if err2 != nil {
		return result, fmt.Errorf("jq command failed: %w", err2)
	}

	return result, nil
}

func main() {
	// Example usage
	res, err := QuerySLBAndExport("my-slb-instance", "output.json")
	if err != nil {
		fmt.Fprintf(os.Stderr, "Execution failed: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("Execution completed. Stderr/Info: %s\n", res)
}

