package main

import (
	"bytes"
	"fmt"
	"os"
	"os/exec"
)

// QuerySLBAndExport executes the aliyun CLI command to describe SLB,
// processes the output with jq, and saves it to the specified file.
// Returns the stdout of the command pipeline and any error encountered.
func QuerySLBAndExport(loadBalancerName string, outputFile string) (string, error) {
	// Use native exec piping instead of `sh -c` to completely eliminate shell injection risks
	// and correctly capture stdout while simultaneously writing to a file.
	aliyunCmd := exec.Command("aliyun", "slb", "DescribeLoadBalancers", "--LoadBalancerName", loadBalancerName)
	jqCmd := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Pipe aliyun stdout to jq stdin
	pipe, err := aliyunCmd.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	jqCmd.Stdin = pipe

	// Capture jq stdout to return it later
	var outBuf bytes.Buffer
	jqCmd.Stdout = &outBuf

	// Capture stderr from both commands for detailed error reporting
	var errBuf bytes.Buffer
	aliyunCmd.Stderr = &errBuf
	jqCmd.Stderr = &errBuf

	// Start jq first to ensure it's ready to read from the pipe before aliyun writes to it
	if err := jqCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start jq: %w", err)
	}
	if err := aliyunCmd.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun: %w", err)
	}

	// Wait for both commands to finish
	if err := aliyunCmd.Wait(); err != nil {
		return "", fmt.Errorf("aliyun command failed: %w, stderr: %s", err, errBuf.String())
	}
	if err := jqCmd.Wait(); err != nil {
		return "", fmt.Errorf("jq command failed: %w, stderr: %s", err, errBuf.String())
	}

	result := outBuf.String()

	// Write the captured output to the specified file
	if err := os.WriteFile(outputFile, []byte(result), 0644); err != nil {
		return result, fmt.Errorf("failed to write output file: %w", err)
	}

	return result, nil
}

