	cmdJq := exec.Command("jq", ".LoadBalancers.LoadBalancer[]")

	// Create a pipe to connect aliyun's stdout to jq's stdin (equivalent to shell '|')
	aliyunStdout, err := cmdAliyun.StdoutPipe()
	if err != nil {
		return "", fmt.Errorf("failed to create stdout pipe: %w", err)
	}
	cmdJq.Stdin = aliyunStdout

	// Open the output file for writing (equivalent to shell '>')
	outFile, err := os.Create(cleanOutputFile)
	if err != nil {
		return "", fmt.Errorf("failed to create output file: %w", err)
	}
	defer outFile.Close()

	// Capture jq's stdout to a buffer for returning, and simultaneously write to the file
	var stdoutBuf bytes.Buffer
	cmdJq.Stdout = io.MultiWriter(outFile, &stdoutBuf)

	// Capture stderr from both commands for error diagnostics
	var stderrBuf bytes.Buffer
	cmdAliyun.Stderr = &stderrBuf
	cmdJq.Stderr = &stderrBuf

	// Start the first command
	if err := cmdAliyun.Start(); err != nil {
		return "", fmt.Errorf("failed to start aliyun command: %w", err)
	}

	// Start the second command
	if err := cmdJq.Start(); err != nil {
		cmdAliyun.Process.Kill()
		return "", fmt.Errorf("failed to start jq command: %w", err)
	}

	// Wait for both commands to complete
	errAliyun := cmdAliyun.Wait()
	errJq := cmdJq.Wait()

	// Handle errors, returning any captured output alongside the error (matches original behavior)
	if errAliyun != nil {
		return stdoutBuf.String(), fmt.Errorf("aliyun command failed: %w, stderr: %s", errAliyun, stderrBuf.String())
	}
	if errJq != nil {
